    public static int opIsScript(int p) {
        // Does the language cell `p` name a SCRIPT (ISO 15924: four letters, the first uppercase) and not a language (P7.S, D215)?
        if (p <= 0) {
            return 0;
        }
        int b0 = p / 16777216;
        int b1 = (p / 65536) % 256;
        int b2 = (p / 256) % 256;
        int b3 = p % 256;
        if (b0 < 65) {
            return 0;
        }
        if (b0 > 90) {
            return 0;
        }
        if (b1 == 0) {
            return 0;
        }
        if (b2 == 0) {
            return 0;
        }
        if (b3 == 0) {
            return 0;
        }
        return 1;
    }
    public static int opScriptReads(int want, int model) {
        // Does a model of script `model` read a request's script `want`? The ideographs are shared: a `Hani` page may be Chinese
        // or Japanese.
        if (want == model) {
            return 1;
        }
        if ((want == scHani()) && (model == scJpan())) {
            return 1;
        }
        return 0;
    }
